import React, { useState } from 'react';

const SearchFilters = ({ onSearch, onClear, filters }) => {
  const [localFilters, setLocalFilters] = useState(filters);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setLocalFilters(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSearch(localFilters);
  };

  const handleClear = () => {
    setLocalFilters({
      location: '',
      type: 'all',
      status: 'all',
      minPrice: '',
      maxPrice: '',
      bedrooms: '',
      searchQuery: ''
    });
    onClear();
  };

  return (
    <div className="search-section-enhanced">
      <div className="container">
        <div className="search-container-glass animated-border">
          <div className="search-header">
            <h2>Refine Your Search</h2>
            <p>Use our advanced filters to find your perfect property</p>
          </div>
          
          <form onSubmit={handleSubmit} className="filters-form">
            <div className="filter-grid">
              {[
                {
                  label: 'Location',
                  icon: '📍',
                  name: 'location',
                  type: 'text',
                  placeholder: 'Enter location',
                  value: localFilters.location
                },
                {
                  label: 'Type',
                  icon: '🏠',
                  name: 'type',
                  type: 'select',
                  options: [
                    { value: 'all', label: 'All Types' },
                    { value: 'house', label: 'House' },
                    { value: 'apartment', label: 'Apartment' },
                    { value: 'studio', label: 'Studio' },
                    { value: 'penthouse', label: 'Penthouse' },
                    { value: 'townhouse', label: 'Townhouse' },
                    { value: 'loft', label: 'Loft' }
                  ],
                  value: localFilters.type
                },
                {
                  label: 'Status',
                  icon: '🏷️',
                  name: 'status',
                  type: 'select',
                  options: [
                    { value: 'all', label: 'All Status' },
                    { value: 'sale', label: 'For Sale' },
                    { value: 'rent', label: 'For Rent' }
                  ],
                  value: localFilters.status
                },
                {
                  label: 'Price Range',
                  icon: '💰',
                  name: 'price',
                  type: 'range',
                  minName: 'minPrice',
                  maxName: 'maxPrice',
                  minValue: localFilters.minPrice,
                  maxValue: localFilters.maxPrice
                },
                {
                  label: 'Bedrooms',
                  icon: '🛏️',
                  name: 'bedrooms',
                  type: 'select',
                  options: [
                    { value: '', label: 'Any' },
                    { value: '1', label: '1+ Bedrooms' },
                    { value: '2', label: '2+ Bedrooms' },
                    { value: '3', label: '3+ Bedrooms' },
                    { value: '4', label: '4+ Bedrooms' },
                    { value: '5', label: '5+ Bedrooms' }
                  ],
                  value: localFilters.bedrooms
                },
                {
                  label: 'Keyword',
                  icon: '🔍',
                  name: 'searchQuery',
                  type: 'text',
                  placeholder: 'Type here to search...',
                  value: localFilters.searchQuery
                }
              ].map((filter, index) => (
                <div key={index} className="filter-group floating-element" style={{ animationDelay: `${index * 0.1}s` }}>
                  <label className="filter-label">
                    <span className="filter-icon">{filter.icon}</span>
                    {filter.label}
                  </label>
                  
                  {filter.type === 'select' ? (
                    <select
                      name={filter.name}
                      value={filter.value}
                      onChange={handleChange}
                      className="filter-select"
                    >
                      {filter.options.map(option => (
                        <option key={option.value} value={option.value}>
                          {option.label}
                        </option>
                      ))}
                    </select>
                  ) : filter.type === 'range' ? (
                    <div className="price-inputs">
                      <input
                        type="number"
                        name={filter.minName}
                        value={filter.minValue}
                        onChange={handleChange}
                        placeholder="Min Price"
                        className="filter-input price"
                      />
                      <span className="price-separator">to</span>
                      <input
                        type="number"
                        name={filter.maxName}
                        value={filter.maxValue}
                        onChange={handleChange}
                        placeholder="Max Price"
                        className="filter-input price"
                      />
                    </div>
                  ) : (
                    <input
                      type={filter.type}
                      name={filter.name}
                      value={filter.value}
                      onChange={handleChange}
                      placeholder={filter.placeholder}
                      className="filter-input"
                    />
                  )}
                </div>
              ))}
            </div>

            <div className="filter-actions">
              <button type="submit" className="btn btn-search floating-element">
                <span className="btn-icon">🔍</span>
                Search Properties
              </button>
              <button 
                type="button" 
                className="btn btn-clear floating-element"
                onClick={handleClear}
                style={{ animationDelay: '0.3s' }}
              >
                Clear Filters
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default SearchFilters;
